float rnd(float x, float n) {
    return fract(abs(1e4*sin(x*10.0+10.0*pow(1.0+x, 2.5)+n*(2.0+x)*(2.0+x))));
}

#define PI 3.1415926538

// easing code ported from https://easings.net/

float ease(float x) {
    return x < 0.5 ? 2.0 * x * x : 1.0 - pow(-2.0 * x + 2.0, 2.0) / 2.0;
}

float bounce(float x) {
    const float n1 = 7.5625;
    const float d1 = 2.75;

    if (x < 1.0 / d1) {
        return n1 * x * x;
    } else if (x < 2.0 / d1) {
        return n1 * (x -= 1.5 / d1) * x + 0.75;
    } else if (x < 2.5 / d1) {
        return n1 * (x -= 2.25 / d1) * x + 0.9375;
    } else {
        return n1 * (x -= 2.625 / d1) * x + 0.984375;
    }
}

float bounceInOut(float x) {
    return x < 0.5
      ? (1.0 - bounce(1.0 - 2.0 * x)) / 2.0
      : (1.0 + bounce(2.0 * x - 1.0)) / 2.0;
}

float rr(float an, float ar, float tn) {
    return (0.5+0.5*rnd(an,tn))*ease(1.0-ar)+(0.5+0.5*rnd(mod(an+1.0,12.0),tn))*ease(ar);
}

float cc(float an, float ar, float tn, float l) {
    float rv = (0.2+0.8*rnd(an,tn))*ease(1.0-ar)+(0.2+0.8*rnd(mod(an+1.0,12.0),tn))*ease(ar);
    rv+=0.5-l*0.5;
    return clamp(rv, 0.0, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float tn = floor(iTime);
    float tr = fract(iTime);
    float l = length(uv);
    float a = 6.0*atan(uv.y, uv.x)/PI+6.0;
    float an = floor(a);
    float ar = fract(a);
    float r0 = rr(an, ar, tn);
    float r1 = rr(an, ar, tn+1.0);
    float r = r0*bounceInOut(1.0-tr)+r1*bounceInOut(tr);
    vec3 col = vec3(0.0, 0.0, 0.0);
    if(l<=r) {
        vec3 cc0;
        vec3 cc1;
        float f = 12.0*l/r;
        float fn = floor(f);
        float fr = fract(f);
        for(int i=0;i<3;++i) {
            cc0[i] = cc(fn, fr, tn+float(i)*127.0,l);
            cc1[i] = cc(fn, fr, tn+float(i)*127.0+1.0,l);
        }
        col = cc0*(1.0-tr)+cc1*tr;
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
